      "difficulty": "normal",
      "topic": "S. pyogenes: necrotizing fasciitis treatment",
      "stem": "A 45-year-old man has pain out of proportion to exam, rapidly spreading dusky erythema, and bullae on his thigh after a minor abrasion. Blood cultures grow group A Streptococcus. Along with emergency debridement and penicillin, which drug is added mainly to suppress toxin production?",
