      "topic": "S. agalactiae: neonatal sepsis",
      "stem": "A 3-day-old term infant is lethargic and febrile with grunting respirations. Lumbar puncture shows neutrophilic pleocytosis. Culture of blood and CSF grows the β-hemolytic colonies shown. They are catalase-negative, bacitracin-resistant, and hippurate-positive, and they enhance the hemolysis of S. aureus. Which antigen is most important to this organism's virulence?",
