      "difficulty": "normal",
      "topic": "S. pneumoniae: lobar pneumonia",
      "stem": "A 67-year-old man has sudden fever, a shaking chill, pleuritic chest pain, and rust-colored sputum. His chest radiograph is shown. Sputum shows lancet-shaped Gram-positive diplococci that are α-hemolytic. Which test result would confirm the most likely organism?",
