      "difficulty": "normal",
      "topic": "Viridans strep: subacute endocarditis",
      "stem": "A 55-year-old man with a history of rheumatic heart disease has 6 weeks of low-grade fever, fatigue, and weight loss after a dental extraction. Blood cultures grow α-hemolytic, optochin-resistant, bile-insoluble Gram-positive cocci in chains. Which bacterial product helps it attach to fibrin-platelet vegetations on damaged valves?",
