      "stem": "A 25-year-old wrestler has a painful, fluctuant 3-cm abscess on his forearm with surrounding erythema. He is otherwise well. Community-acquired MRSA is common in his area. Which virulence factor, common in community MRSA strains, is associated with leukocyte destruction and necrotic skin infections?",
