      "difficulty": "normal",
      "topic": "Actinomyces: sulfur granules",
      "stem": "A 45-year-old man with poor dentition develops a firm, slowly enlarging mass at the angle of his jaw that drains through multiple sinus tracts. The yellow grains in the drainage are examined histologically, as shown. The organism is a Gram-positive, branching, non–acid-fast anaerobe. What is the treatment of choice?",
