      "topic": "N. meningitidis: complement deficiency",
      "stem": "A 22-year-old man has his second episode of meningococcal meningitis. Other infections have been uncommon. Which laboratory abnormality is most likely?",
      "options": {
        "A": "Absent B cells on flow cytometry",
        "B": "Abnormal dihydrorhodamine flow test",
        "C": "Deficiency of C1 esterase inhibitor",
        "D": "Low total hemolytic complement (CH50) from a deficiency of C5–C9",
        "E": "Low serum IgA with normal IgG"
      },
      "answer": "D",
      "explanation": "Terminal complement components (C5–C9) form the membrane attack complex, which is especially important for killing Neisseria. Deficiency causes recurrent Neisseria bacteremia and meningitis, screened with a low CH50. Eculizumab and ravulizumab (anti-C5) cause the same susceptibility, so patients need meningococcal vaccination before starting them. C1-INH deficiency causes hereditary angioedema."
