      "difficulty": "normal",
      "topic": "H. influenzae type b: epiglottitis",
      "stem": "A 3-year-old unvaccinated child has high fever, drooling, muffled voice, and sits leaning forward. The lateral neck radiograph is shown. Which bacterial structure is the main virulence factor and the target of the vaccine that would have prevented this?",
