      "stem": "A 12-year-old boy with cystic fibrosis has worsening cough and sputum. Sputum grows a non–lactose-fermenting, oxidase-positive Gram-negative rod with a grape-like odor. It produces the water-soluble blue-green pigment shown in the left tube. Which bacterial product causes the pigment and contributes to tissue damage?",
