      "stem": "Several toddlers at a daycare develop fever, abdominal cramps, and frequent small-volume stools with blood and mucus. Stool culture grows a non-motile, non–lactose-fermenting Gram-negative rod that does not produce H2S. Which feature explains the very low infectious dose?",
