      "difficulty": "normal",
      "topic": "RMSF: pathogenesis",
      "stem": "Rickettsia rickettsii infects and multiplies inside a particular host cell type, which causes the rash, edema, hypotension, and multiorgan damage of Rocky Mountain spotted fever. Which cell type is it?",
      "options": {
        "A": "Monocytes",
        "B": "Vascular endothelial cells",
        "C": "Neutrophils",
        "D": "Hepatocytes",
        "E": "Erythrocytes"
      },
      "answer": "B",
      "explanation": "Rickettsiae are obligate intracellular bacteria. They cannot make their own CoA and NAD+ and must take them from host cells. R. rickettsii infects endothelial (and vascular smooth muscle) cells, causing widespread vasculitis, increased vascular permeability, edema, hypovolemia, hyponatremia, thrombocytopenia, and petechial or necrotic skin lesions. Encephalitis and noncardiogenic pulmonary edema can occur. Classic triad: headache, fever, rash."
