      "stem": "A 19-year-old military recruit has 2 weeks of low-grade fever, headache, sore throat, and a persistent dry cough. He looks well, but CXR shows patchy bilateral interstitial infiltrates that look worse than the exam. His blood agglutinates when cooled to 4°C. Why is amoxicillin ineffective against the most likely organism?",
