      "difficulty": "normal",
      "topic": "Whipple disease",
      "stem": "A 55-year-old white man has chronic diarrhea with steatorrhea, weight loss, migratory arthralgias, and memory problems. A duodenal biopsy is shown after periodic acid-Schiff (PAS) staining: the lamina propria is packed with foamy, PAS-positive macrophages. What is the most likely organism?",
