      "tag": "Mycoplasma & Other Bacteria",
      "difficulty": "normal",
      "topic": "Chancroid",
      "stem": "A 26-year-old man who recently visited Southeast Asia has a painful, soft genital ulcer with ragged, undermined edges and a gray purulent base, plus a painful, fluctuant inguinal node. Gram stain shows Gram-negative coccobacilli in parallel chains ('school of fish'). What is the treatment?",
