      "explanation": "Neonatal HSV is usually caught during delivery through an infected birth canal. The risk is highest with a primary maternal infection near term, because there is a lot of virus and no protective maternal IgG. Active lesions or prodromal symptoms at labor call for cesarean delivery. Suppressive acyclovir from 36 weeks is used for women with recurrent herpes. Neonatal HSV can be localized (skin, eyes, mouth), CNS, or disseminated, and is treated with IV acyclovir."
