      "explanation": "Norovirus (Caliciviridae, naked positive-sense ssRNA) is the most common cause of viral gastroenteritis in adults and of outbreaks in closed settings (cruise ships, nursing homes, schools). The infectious dose is very low. It survives on surfaces and resists alcohol. Soap and water and bleach cleaners are needed. Immunity is short-lived and strain-specific. It damages small intestinal villi (brush border)."
