      "topic": "Rotavirus",
      "stem": "A 9-month-old unvaccinated infant in winter has vomiting, fever, and profuse watery diarrhea causing dehydration. Stool antigen testing finds a non-enveloped, segmented, double-stranded RNA virus. Which rare adverse effect is associated with the oral vaccine that prevents it?",
