      "explanation": "Yellow fever (flavivirus, Aedes aegypti) has a jungle cycle with monkeys and an urban cycle with humans. Severe cases cause hepatitis (jaundice), hemorrhage (black vomit), and kidney failure. The liver shows Councilman bodies (apoptotic hepatocytes). Prevent it with the live attenuated 17D vaccine, which is required for travel to endemic areas and contraindicated in severe immunosuppression and infants under 6 months."
