      "explanation": "Zika virus (flavivirus) is spread mainly by Aedes mosquitoes, and also sexually and from mother to fetus. It infects neural progenitor cells, causing congenital Zika syndrome: severe microcephaly, subcortical calcifications, eye abnormalities, and contractures. In adults it is usually mild but is associated with Guillain-Barré syndrome."
