      "stem": "A newborn has cataracts, sensorineural deafness, a continuous machine-like murmur, and the 'blueberry muffin' skin lesions shown. The mother, recently immigrated, had a mild rash with postauricular lymphadenopathy in the first trimester. Which virus is responsible?",
