      "answer": "B",
      "explanation": "SARS-CoV-2 is an enveloped, positive-sense ssRNA coronavirus. Its spike (S) protein binds angiotensin-converting enzyme 2 (ACE2), found on respiratory epithelium, type II pneumocytes, and endothelium. Host proteases (TMPRSS2 or cathepsins) prime fusion. mRNA vaccines encode the spike protein. Nirmatrelvir (with ritonavir boosting) inhibits the main protease (Mpro), and remdesivir inhibits RNA-dependent RNA polymerase."
