      "stem": "A 62-year-old woman has rapidly progressive dementia over 4 months, with myoclonic jerks triggered by startle. EEG shows periodic sharp wave complexes, and MRI shows cortical ribboning and basal ganglia hyperintensity. Brain biopsy shows spongiform change without inflammation. What is the molecular basis?",
