      "explanation": "HIV gp120 binds CD4, then a co-receptor: CCR5 (macrophage-tropic, R5, early infection) or CXCR4 (T-cell-tropic, X4, later). gp41 then causes fusion. Homozygous CCR5-Δ32 gives strong resistance to R5 strains, and heterozygotes progress more slowly. Maraviroc blocks CCR5 and requires a tropism assay first. Enfuvirtide binds gp41 and blocks fusion."
