      "explanation": "HIV structural genes: gag makes p24 capsid, p17 matrix, and nucleocapsid. pol makes reverse transcriptase, integrase, and protease. env makes gp160, which host proteases cleave into gp120 (attachment) and gp41 (fusion). Regulatory genes: tat (transactivation of transcription), rev (nuclear export of unspliced mRNA), and nef (downregulates MHC I and CD4). HIV is a diploid, positive-sense ssRNA retrovirus."
