      "explanation": "Acute retroviral syndrome is a mono-like illness 2–4 weeks after infection. Viral load is very high and the patient is highly contagious. Antibodies may not have formed yet, but p24 antigen and HIV RNA are detectable. The 4th-generation Ag/Ab assay is the screening test, followed by an HIV-1/HIV-2 differentiation immunoassay and then HIV RNA if indeterminate. Western blot is no longer used. Infants born to HIV-positive mothers are tested with HIV RNA/DNA PCR because maternal IgG crosses the placenta."
