      "answer": "A",
      "explanation": "NRTIs (tenofovir, emtricitabine, lamivudine, abacavir, zidovudine) are nucleoside or nucleotide analogs. Host kinases phosphorylate them (tenofovir is already a nucleotide), and they terminate DNA chains synthesized by reverse transcriptase. Class toxicity: mitochondrial toxicity and lactic acidosis. Specific toxicities: abacavir hypersensitivity (HLA-B*57:01), tenofovir disoproxil nephrotoxicity (Fanconi syndrome) and bone loss, zidovudine bone marrow suppression (macrocytic anemia). Lamivudine, emtricitabine, and tenofovir also treat HBV."
