      "topic": "HIV: integrase & protease inhibitors",
      "stem": "A patient on an HIV regimen boosted with ritonavir develops hyperglycemia, dyslipidemia, and redistribution of fat to the abdomen and dorsocervical area. Why is ritonavir added to other drugs of its class?",
