      "explanation": "Protease inhibitors (-navir: darunavir, atazanavir, lopinavir) block HIV protease cleavage of the Gag-Pol polyprotein, producing immature, non-infectious virions. Low-dose ritonavir (or cobicistat) inhibits CYP3A4 to 'boost' other PIs. PI toxicities: hyperglycemia, dyslipidemia, lipodystrophy, GI upset, many drug interactions (rifampin lowers PI levels, so rifabutin is used), and atazanavir hyperbilirubinemia. Integrase inhibitors (-tegravir: dolutegravir, bictegravir, raltegravir) block strand transfer. They are first-line and can cause weight gain and increased CK."
