      "answer": "E",
      "explanation": "The goal is an undetectable viral load. If the viral load near delivery is above 1,000 copies/mL: IV zidovudine during labor and scheduled cesarean at 38 weeks. All exposed infants receive antiretroviral prophylaxis (zidovudine, or combination therapy if high risk). In the US, avoiding breastfeeding is still recommended, although shared decision-making is now allowed for women with sustained viral suppression."
