      "difficulty": "normal",
      "topic": "HIV: IRIS",
      "stem": "Three weeks after starting ART, a man with AIDS (CD4 count 20/μL) who is being treated for cryptococcal meningitis develops worsening headache and fever. His CD4 count has risen and his viral load has fallen sharply. CSF cultures are now sterile. What is the most likely explanation?",
