      "answer": "C",
      "explanation": "IRIS is a paradoxical inflammatory worsening of a known infection (or unmasking of an occult one) as the recovering immune system responds to antigens from Cryptococcus, TB, MAC, CMV, PML, and others. Risk is highest with very low baseline CD4 and rapid viral suppression. For cryptococcal meningitis, ART is delayed 4–6 weeks after starting antifungals to reduce this risk. For TB, ART is started within 2 weeks unless there is TB meningitis."
