      "explanation": "Dermatophytes (Trichophyton, Microsporum, Epidermophyton) digest keratin in skin, hair, and nails, causing tinea corporis (ringworm), cruris, pedis, capitis, and onychomycosis (tinea unguium). Terbinafine inhibits squalene epoxidase, and toxic squalene builds up. It concentrates in keratin and is first-line for onychomycosis. Monitor LFTs. Griseofulvin disrupts microtubule spindles, deposits in keratin, and is used for tinea capitis in children. It is teratogenic and induces CYP450. Topical azoles or terbinafine treat tinea corporis."
