      "stem": "A 25-year-old soldier treated for malaria after deployment in Afghanistan has another episode 7 months later. His blood smear 7 months earlier showed enlarged RBCs with stippling (Schüffner dots) and an amoeboid trophozoite, as shown. Which drug should have been added to prevent relapse, and what test is required first?",
