      "topic": "Listeria: epidemiology",
      "stem": "A multistate outbreak of febrile illness, meningitis, and pregnancy loss is traced to cantaloupe and deli meat stored in refrigerators. Which property of the pathogen explains why refrigeration did not prevent the outbreak?",
