      "difficulty": "normal",
      "topic": "Botulism: wound & adult",
      "stem": "A 32-year-old man who injects black tar heroin under the skin develops diplopia, ptosis, dysphagia, and descending weakness. He has no GI symptoms. What is the most likely mechanism of disease, and what is the key treatment?",
      "options": {
        "A": "Guillain-Barré: molecular mimicry; give IVIG",
        "B": "Myasthenia gravis: anti-AChR antibodies; give pyridostigmine",
        "C": "Wound botulism: spores germinate in the abscess and make toxin; give equine heptavalent antitoxin",
        "D": "Foodborne botulism: preformed toxin; give human botulism immune globulin (BabyBIG)",
        "E": "Tetanus: toxin blocks glycine release; give diazepam only"
      },
      "answer": "C",
      "explanation": "Wound botulism happens when spores in contaminated drugs or soil germinate in anaerobic, devitalized tissue (skin popping with black tar heroin). Adult botulism of any type is treated with heptavalent equine antitoxin as early as possible, plus wound debridement and ventilator support. Antitoxin neutralizes only circulating toxin, so recovery requires regrowth of nerve terminals over weeks. The same toxin (onabotulinumtoxinA) is used therapeutically for dystonia, spasticity, and migraine."
