      "stem": "A 19-year-old with cystic fibrosis develops rapidly progressive necrotizing pneumonia and bacteremia. Sputum grows a Gram-negative rod resistant to aminoglycosides and polymyxins. This organism is a contraindication to lung transplant in many centers. What is it?",
