      "stem": "A 55-year-old diabetic man from Taiwan has fever, a single large liver abscess, and sudden vision loss from endophthalmitis. Culture grows hypermucoviscous Klebsiella pneumoniae that forms a long 'string' when a colony is stretched. The isolate makes an extended-spectrum β-lactamase. What is the treatment of choice?",
