      "topic": "Serratia & Enterobacter: AmpC",
      "stem": "A patient with Enterobacter cloacae bacteremia initially responds to ceftriaxone, but a repeat culture now shows resistance to all third-generation cephalosporins. What is the most likely mechanism, and which drug is preferred?",
